#!/usr/bin/env node
/**
 * Bundles the security migrations into one file you can paste into the Supabase
 * SQL editor. Generated from the migrations themselves, so it can't drift.
 *
 *   node scripts/sql-bundle.mjs [name...]      # defaults to rls + storage
 *
 * Writes .logs/apply.sql
 */
import { readFile, readdir, writeFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const MIGRATIONS = path.resolve(HERE, "../supabase/migrations");
const OUT_DIR = path.resolve(HERE, "../.logs");
const OUT = path.join(OUT_DIR, "apply.sql");

const filters = process.argv.slice(2);
const match = filters.length ? filters : ["rls_policies", "storage"];

const files = (await readdir(MIGRATIONS))
  .filter((name) => name.endsWith(".sql"))
  .filter((name) => match.some((token) => name.includes(token)))
  .sort();

if (!files.length) {
  console.error(`No migrations matched: ${match.join(", ")}`);
  process.exit(1);
}

const parts = [
  "-- ===========================================================================",
  "-- Generated by scripts/sql-bundle.mjs — do not edit.",
  "-- Paste into the Supabase SQL editor and run. Safe to run more than once.",
  `-- Sources: ${files.join(", ")}`,
  "-- ===========================================================================",
  "",
  "begin;",
  "",
];

for (const file of files) {
  parts.push(`-- ---------- ${file} ----------`, await readFile(path.join(MIGRATIONS, file), "utf8"), "");
}

parts.push("commit;", "");

await mkdir(OUT_DIR, { recursive: true });
await writeFile(OUT, parts.join("\n"), "utf8");

console.log(`Wrote ${OUT}`);
console.log(`Includes: ${files.join(", ")}`);
